using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using Comfort.Common;
using EFT;
using EFT.Ballistics;
using EFT.HealthSystem;
using HarmonyLib;
using UnityEngine;
using Object=UnityEngine.Object;
namespace LocalSpt5Esp;
internal static class AiActorControl {
 sealed class Settings {internal Player Actor=null!;internal IntPtr Health;internal bool IgnorePlayer;internal float Damage=1;}
 static readonly Dictionary<IntPtr,Settings> actors=new();static readonly Dictionary<IntPtr,Settings> healths=new();static readonly HashSet<IntPtr> neutralOwners=new();static readonly AiRelationTable relations=new();
 static readonly Dictionary<IntPtr,string> identities=new();
 static readonly List<Player> targets=new(),sideA=new(),sideB=new();static IntPtr world;static Player? local;static string localProfile="",notice="",multiplier="1",damage="10";static bool teamMode=true;static float nextTick,nextWarning;static Vector2 scroll;
 internal static bool Open=>targets.Count>0;
 internal static void Reset(){actors.Clear();healths.Clear();neutralOwners.Clear();identities.Clear();relations.Clear();targets.Clear();sideA.Clear();sideB.Clear();world=IntPtr.Zero;local=null;localProfile="";nextTick=0;}
 internal static void Close()=>targets.Clear();
 internal static void Select(GameWorld current,IEnumerable<Player> selected){targets.Clear();targets.AddRange(selected.Where(p=>p!=null&&p.IsAI&&!p.IsYourPlayer));foreach(var target in targets){if(identities.TryGetValue(target.Pointer,out var original)&&original!=target.ProfileId)throw new ArgumentException("AI 实体已被替换，请重新进入管理列表。");identities[target.Pointer]=target.ProfileId;}world=current.Pointer;local=current.MainPlayer;localProfile=local?.ProfileId??"";notice="修改仅作用于当前战局；可单选或多选 AI。";scroll=Vector2.zero;if(targets.Count==1&&actors.TryGetValue(targets[0].Pointer,out var settings))multiplier=settings.Damage.ToString(CultureInfo.InvariantCulture);}
 internal static string Team(BotOwner bot)=>bot.BotsGroup is BotsGroup group?"队伍 #"+group.Id+" · "+group.MembersCount+" 人":"未分队";
 static Player Require(Player p){var current=Singleton<GameWorld>.Instance;bool present=false;var list=current?.AllAlivePlayersList;if(list!=null)for(int i=0;i<list.Count;i++)if(list[i]?.Pointer==p.Pointer){present=true;break;}if(!present||!AiControlRules.SameActor(world.ToInt64(),p.Pointer.ToInt64(),identities.GetValueOrDefault(p.Pointer,""),current?.Pointer.ToInt64()??0,p.Pointer.ToInt64(),p.ProfileId,p.IsAI,p.IsYourPlayer,p.HealthController?.IsAlive==true))throw new ArgumentException("AI 已离开当前战局或已死亡，请重新选择。");return p;}
 static Settings For(Player p){Require(p);if(!actors.TryGetValue(p.Pointer,out var settings)){settings=new(){Actor=p,Health=p.ActiveHealthController?.Pointer??IntPtr.Zero};actors[p.Pointer]=settings;if(settings.Health!=IntPtr.Zero)healths[settings.Health]=settings;}return settings;}
 internal static bool Ignored(BotOwner? owner,IPlayer? target){if(owner==null||target==null)return false;if(neutralOwners.Count>0&&neutralOwners.Contains(owner.Pointer)&&target.ProfileId==localProfile&&owner.GetPlayer is Player actor&&identities.GetValueOrDefault(actor.Pointer)==actor.ProfileId&&actors.TryGetValue(actor.Pointer,out var entry)&&entry.IgnorePlayer)return true;return Relation(owner,target)==false;}
 internal static bool? Relation(BotOwner owner,IPlayer target){if(relations.Actors.Count==0&&relations.Teams.Count==0)return null;var p=owner.GetPlayer;if(p==null)return null;return relations.Resolve(p.ProfileId,target.ProfileId,owner.BotsGroup?.Id,target.AIData?.BotOwner?.BotsGroup?.Id);}
 internal static bool EnemyOverride(BotEnemiesController controller,IPlayer target,ref bool result){if(Ignored(controller._owner,target)){result=false;return false;}if(controller._owner!=null&&Relation(controller._owner,target) is bool value){result=value;return false;}return true;}
 static bool Ally(BotsGroup __instance,IPlayer __0,ref bool __result){var other=__0?.AIData?.BotOwner?.BotsGroup;if(other!=null&&relations.Teams.TryGetValue((__instance.Id,other.Id),out bool hostile)){__result=false;return false;}return true;}
 internal static bool GroupOverride(BotsGroup group,IPlayer target,ref bool result){var other=target.AIData?.BotOwner?.BotsGroup;if(other!=null&&relations.Teams.TryGetValue((group.Id,other.Id),out bool value)){result=value;return false;}return true;}
 internal static bool ScaleDamage(ActiveHealthController controller,DamageInfo info,ref float amount,ref float result){if(healths.Count==0||info==null||info.OverDamageFrom.HasValue||!healths.TryGetValue(controller.Pointer,out var settings)||settings.Damage==1)return true;if(info.Player?.iPlayer?.ProfileId!=localProfile||settings.Actor?.IsYourPlayer!=false||settings.Actor.ActiveHealthController?.Pointer!=controller.Pointer||identities.GetValueOrDefault(settings.Actor.Pointer)!=settings.Actor.ProfileId)return true;if(settings.Damage==0){result=0;return false;}float available=controller.GetBodyPartHealth(EBodyPart.Common,false).Current;amount=AiControlRules.Damage(amount,settings.Damage,available);return true;}
 internal static void Initialize(Plugin plugin){plugin.Patches.Patch(AccessTools.Method(typeof(BotsGroup),"IsAlly"),prefix:new HarmonyMethod(typeof(AiActorControl),nameof(Ally)));plugin.Patches.Patch(AccessTools.PropertySetter(typeof(BotMemory),"GoalEnemy"),prefix:new HarmonyMethod(typeof(AiActorControl),nameof(Goal)));plugin.Patches.Patch(AccessTools.Method(typeof(BotGroupHostility),"UpdatePlayerHostilityCollection"),prefix:new HarmonyMethod(typeof(AiActorControl),nameof(GroupStatus)));}
 static void Goal(BotMemory __instance,ref EnemyInfo __0){if(__0!=null&&Ignored(__instance._owner,__0.Person))__0=null!;}
 static void GroupStatus(BotGroupHostility __instance,IPlayer __0,ref HostilityEvaluationResult __1){var from=__instance.OwnedGroup;var to=__0?.AIData?.BotOwner?.BotsGroup;if(from!=null&&to!=null&&relations.Teams.TryGetValue((from.Id,to.Id),out bool hostile))__1=new HostilityEvaluationResult(hostile?BotHostilityStatus.Enemy:BotHostilityStatus.Neutral,"Local AI team control");}
 internal static void Forget(BotOwner owner,IPlayer target){var memory=owner.Memory;if(memory==null)return;bool aiming=memory.GoalEnemy?.Person?.ProfileId==target.ProfileId;if(aiming){owner.GetPlayer?.HandsController?.TryCast<Player.FirearmController>()?.SetTriggerPressed(false);memory.GoalEnemy=null!;}if(memory.LastEnemy?.Person?.ProfileId==target.ProfileId)memory.LastEnemy=null!;if(owner.EnemiesController?.EnemyInfos?.ContainsKey(target)==true)owner.EnemiesController.Remove(target);}
 static void EnsureEnemy(BotOwner owner,IPlayer target){var enemies=owner.EnemiesController;var group=owner.BotsGroup;if(enemies==null||group==null)return;var info=enemies.EnemyInfos.ContainsKey(target)?enemies.EnemyInfos[target]:enemies.AddNew(group,target,new BotGroupEnemyInfo(target,group));if(info!=null){info.IgnoreUntilAggression=false;info.SetIgnoreState(false);}}
 internal static void Tick(GameWorld? current,Player? player){if(current==null||player==null){if(world!=IntPtr.Zero)Reset();return;}if(world!=IntPtr.Zero&&world!=current.Pointer)Reset();world=current.Pointer;local=player;localProfile=player.ProfileId;if(actors.Count==0&&relations.Actors.Count==0&&relations.Teams.Count==0||Time.unscaledTime<nextTick)return;nextTick=Time.unscaledTime+.5f;try{foreach(var settings in actors.Values)if(settings.IgnorePlayer&&settings.Actor?.HealthController?.IsAlive==true&&settings.Actor.AIData?.BotOwner is BotOwner owner)Forget(owner,player);var all=current.AllAlivePlayersList;if(all==null)return;if(relations.Actors.Count==0&&relations.Teams.Count==0)return;var bots=new List<(Player Player,BotOwner Owner,string Profile,int? Team)>();for(int i=0;i<all.Count;i++){var p=all[i];if(p?.IsAI!=true||p.HealthController?.IsAlive!=true||p.AIData?.BotOwner is not BotOwner owner)continue;bots.Add((p,owner,p.ProfileId,owner.BotsGroup?.Id));}foreach(var source in bots)foreach(var target in bots){if(source.Player.Pointer==target.Player.Pointer)continue;var rule=relations.Resolve(source.Profile,target.Profile,source.Team,target.Team);if(rule==null)continue;var group=source.Owner.BotsGroup;if(source.Team.HasValue&&target.Team.HasValue&&relations.Teams.ContainsKey((source.Team.Value,target.Team.Value))&&group!=null&&group.Enemies.ContainsKey(target.Player)!=rule.Value)group.BotGroupHostility?.UpdatePlayerHostilityCollection(target.Player,new HostilityEvaluationResult(rule.Value?BotHostilityStatus.Enemy:BotHostilityStatus.Neutral,"Local control"));if(rule==false)Forget(source.Owner,target.Player);else EnsureEnemy(source.Owner,target.Player);}}catch(Exception e){if(Time.unscaledTime>=nextWarning){nextWarning=Time.unscaledTime+10;Plugin.Self.Log.LogWarning("AI relation update: "+e.Message);}}}
 static void Ignore(bool value){int changed=0;foreach(var target in targets){var p=Require(target);var settings=For(p);settings.IgnorePlayer=value;var owner=p.AIData?.BotOwner;if(owner==null)continue;if(value){neutralOwners.Add(owner.Pointer);if(local!=null)Forget(owner,local);}else{neutralOwners.Remove(owner.Pointer);if(local!=null&&owner.BotsGroup?.Enemies.ContainsKey(local)==true)owner.Memory?.AddEnemyInfo(local,owner.BotsGroup.Enemies[local],false);}changed++;}notice=$"已将 {changed} 名 AI 的对玩家敌对设置为 "+(value?"关闭。":"原生规则。");FeatureToasts.Show(notice);}
 static void Multiplier(){float value=ItemSpawnRules.Number(multiplier,0,float.MaxValue,"承受玩家伤害倍率");foreach(var target in targets)For(target).Damage=value;notice="已设置承受玩家伤害倍率："+value.ToString("G6");FeatureToasts.Show(notice);}
 static void Hurt(){var current=Singleton<GameWorld>.Instance;if(current?.Pointer!=world||local?.HealthController?.IsAlive!=true)throw new ArgumentException("需要存活的本地玩家作为伤害来源。");float value=ItemSpawnRules.Number(damage,0,float.MaxValue,"施加伤害");int affected=0;float lost=0;var bridge=new PlayerBridge(local).Cast<IObserverToPlayerBridge>();foreach(var target in targets.ToArray()){var p=Require(target);var health=p.ActiveHealthController??throw new ArgumentException("AI 生命控制器尚未就绪。");float before=health.GetBodyPartHealth(EBodyPart.Common,false).Current;float effective=Math.Min(value,before);var info=new DamageInfo{DamageType=EDamageType.Bullet,Damage=effective,Player=bridge,MasterOrigin=local.Position,HitPoint=p.Position+Vector3.up,Direction=(p.Position-local.Position).normalized,SourceId="local-ai-control"};p.LastAggressor=local;health.ApplyDamage(EBodyPart.Chest,effective,info);lost+=Math.Max(0,before-health.GetBodyPartHealth(EBodyPart.Common,false).Current);affected++;}notice=$"已对 {affected} 名 AI 提交玩家来源伤害；实际扣血合计 {lost:G6}。受伤害倍率与 AI 无敌设置影响。";FeatureToasts.Show("玩家来源伤害已执行");}
 static void Side(List<Player> destination){destination.Clear();foreach(var target in targets)destination.Add(Require(target));notice="已选定 "+destination.Count+" 名 AI 作为关系一方。";}
 static void SetRelations(bool hostile){if(sideA.Count==0||sideB.Count==0)throw new ArgumentException("请先从 AI 列表选择双方，并分别设为 A、B。");var a=sideA.Select(Require).ToArray();var b=sideB.Select(Require).ToArray();foreach(var left in a)foreach(var right in b){if(left.Pointer==right.Pointer)throw new ArgumentException("关系双方不能包含同一个 AI。");if(teamMode){var first=left.AIData?.BotOwner?.BotsGroup??throw new ArgumentException("A 方 AI 没有队伍。");var second=right.AIData?.BotOwner?.BotsGroup??throw new ArgumentException("B 方 AI 没有队伍。");if(first.Id==second.Id)throw new ArgumentException("双方属于同一队伍。");}else if(hostile&&left.AIData?.BotOwner?.BotsGroup?.Pointer==right.AIData?.BotOwner?.BotsGroup?.Pointer)throw new ArgumentException("同队 AI 的攻击受队友保护规则约束，请选择不同队伍。");}
  foreach(var left in a)foreach(var right in b){if(teamMode){var first=left.AIData.BotOwner.BotsGroup;var second=right.AIData.BotOwner.BotsGroup;relations.TeamPair(first.Id,second.Id,hostile);first.BotGroupHostility?.UpdatePlayerHostilityCollection(right,new HostilityEvaluationResult(hostile?BotHostilityStatus.Enemy:BotHostilityStatus.Neutral,"Local control"));second.BotGroupHostility?.UpdatePlayerHostilityCollection(left,new HostilityEvaluationResult(hostile?BotHostilityStatus.Enemy:BotHostilityStatus.Neutral,"Local control"));}else relations.ActorPair(left.ProfileId,right.ProfileId,hostile);}nextTick=0;notice=(teamMode?"双方整队":"所选 AI 双方")+"已设为"+(hostile?"互相敌对。":"互相停战。");FeatureToasts.Show(notice);
 }
 static void RestoreRelations(){var list=Singleton<GameWorld>.Instance?.AllAlivePlayersList;var live=new List<Player>();if(list!=null)for(int i=0;i<list.Count;i++)if(list[i]?.IsAI==true&&list[i].HealthController?.IsAlive==true)live.Add(list[i]);foreach(var actor in live){var owner=actor.AIData?.BotOwner;if(owner==null)continue;foreach(var target in live)if(target.Pointer!=actor.Pointer&&Relation(owner,target).HasValue)Forget(owner,target);}var groups=live.Select(p=>p.AIData?.BotOwner?.BotsGroup).Where(group=>group!=null).GroupBy(group=>group!.Pointer).Select(group=>group.First()).ToArray();relations.Clear();foreach(var group in groups)group?.BotGroupHostility?.OwnedGroupCalcActionNextFrame();notice="已清除自定义敌人记忆并交还原生仇恨判断。";}

 internal static int Delete(IEnumerable<Player> selected){var current=Singleton<GameWorld>.Instance??throw new ArgumentException("请进入战局。");var controller=Singleton<AbstractGame>.Instance?.TryCast<IBotGame>()?.BotsController??throw new ArgumentException("AI 控制器未就绪。");var spawner=controller.GetSpawner()??throw new ArgumentException("AI 生成器未就绪。");var valid=selected.Select(Require).ToArray();int removed=0;foreach(var p in valid){var owner=p.AIData?.BotOwner;if(owner==null)continue;var go=p.gameObject;AiTestControl.ForgetActor(p.ProfileId);neutralOwners.Remove(owner.Pointer);if(actors.Remove(p.Pointer,out var settings))healths.Remove(settings.Health);owner.Deactivate();spawner.DeletePlayer(p);bool registered=false;for(int i=0;i<current.AllAlivePlayersList.Count;i++)if(current.AllAlivePlayersList[i]?.Pointer==p.Pointer){registered=true;break;}if(registered)current.UnregisterPlayer(p.Cast<IPlayer>());owner.Dispose(true);p.Dispose();if(go!=null)Object.Destroy(go);removed++;}targets.RemoveAll(p=>valid.Any(v=>v.Pointer==p.Pointer));return removed;}
 static void Action(Action action){try{action();}catch(Exception e){notice=e.Message;Plugin.Self.Log.LogWarning("AI actor control: "+e.Message);}}
 internal static void Draw(Rect rect){float x=rect.x,y=rect.y,w=rect.width;if(InterfaceMenu.Button(new Rect(x,y,124,30),"返回 AI 列表")){Close();return;}InterfaceMenu.Label(new Rect(x+138,y,w-138,30),"AI 设置 · 已选 "+targets.Count,InterfaceMenu.Accent,18);y+=42;scroll=GUI.BeginScrollView(new Rect(x,y,w,rect.yMax-y-64),scroll,new Rect(0,0,w-20,740));float width=w-28,top=4;InterfaceMenu.Paragraph(new Rect(6,top,width,54),string.Join("；",targets.Take(8).Select(p=>(p.Profile?.Nickname??p.ProfileId)+" · "+(p.AIData?.BotOwner is BotOwner bot?Team(bot):"未分队")))+(targets.Count>8?"…":""),null,12);top+=64;
  if(InterfaceMenu.Button(new Rect(6,top,(width-8)/2,32),"关闭所选 AI 对玩家敌对"))Action(()=>Ignore(true));if(InterfaceMenu.Button(new Rect(14+(width-8)/2,top,(width-8)/2,32),"恢复所选 AI 原生敌对判断"))Action(()=>Ignore(false));top+=46;
  InterfaceMenu.Label(new Rect(6,top,width,26),"承受本地玩家伤害倍率：0 免疫，1 原始；不影响 AI 之间的伤害",null,12);top+=32;multiplier=InterfaceMenu.Field(new Rect(6,top,140,30),multiplier);if(InterfaceMenu.Button(new Rect(156,top,180,30),"应用到所选 AI"))Action(Multiplier);top+=46;
  InterfaceMenu.Label(new Rect(6,top,width,26),"凭空施加伤害 · 来源记为本地玩家 · 作用胸部",InterfaceMenu.Accent,14);top+=34;damage=InterfaceMenu.Field(new Rect(6,top,140,30),damage);if(InterfaceMenu.Button(new Rect(156,top,180,30),"对所选 AI 施加伤害"))Action(Hurt);top+=48;
  InterfaceMenu.Label(new Rect(6,top,width,28),"AI／队伍关系 · A ↔ B",InterfaceMenu.Accent,16);top+=38;if(InterfaceMenu.Button(new Rect(6,top,(width-8)/2,32),"将当前所选设为 A 方"))Action(()=>Side(sideA));if(InterfaceMenu.Button(new Rect(14+(width-8)/2,top,(width-8)/2,32),"将当前所选设为 B 方"))Action(()=>Side(sideB));top+=42;InterfaceMenu.Paragraph(new Rect(6,top,width,52),"A："+string.Join("、",sideA.Select(p=>p.Profile?.Nickname??p.ProfileId))+"\nB："+string.Join("、",sideB.Select(p=>p.Profile?.Nickname??p.ProfileId)),null,12);top+=62;if(InterfaceMenu.Button(new Rect(6,top,width,30),teamMode?"作用范围：双方整支队伍（包括其余成员）":"作用范围：双方选中的 AI"))teamMode=!teamMode;top+=42;if(InterfaceMenu.Button(new Rect(6,top,(width-8)/2,32),"A ↔ B 互相敌对"))Action(()=>SetRelations(true));if(InterfaceMenu.Button(new Rect(14+(width-8)/2,top,(width-8)/2,32),"A ↔ B 互相停战"))Action(()=>SetRelations(false));top+=44;if(InterfaceMenu.Button(new Rect(6,top,width,30),"恢复全部自定义 AI／队伍关系"))Action(RestoreRelations);top+=42;InterfaceMenu.Paragraph(new Rect(6,top,width,60),"当前覆盖：单体关系 "+relations.Actors.Count/2+" 对，队伍关系 "+relations.Teams.Count/2+" 对。队伍编号见 AI 列表；整队设置作用于该队现有与后续成员。",null,12);GUI.EndScrollView();InterfaceMenu.Paragraph(new Rect(x,rect.yMax-58,w,54),notice,InterfaceMenu.Accent,12);
 }
}
